package vn.svframe.svframelib.api.crafting.recipes; import vn.svframe.svframelib.api.crafting.ingredients.*; import vn.svframe.svframelib.api.util.Ref; import net.minecraft.item.ItemStack; import java.util.*; public class ShapelessRecipe extends SVFrameRecipe implements VanillaBookableRecipe { public ShapelessRecipe(String n,ArrayList<SVFrameRecipeIngredient> i){super(n,i);} public ShapelessRecipe(String n,SVFrameRecipeIngredient... i){super(n,i);} public void addIngredient(SVFrameRecipeIngredient i){ingredients.add(i);} public SVFrameRecipeStation getType(){return SVFrameRecipeStation.WORKBENCH;} public SVFrameRecipeInventory matches(SVFrameRecipeInventory inv,Ref<Integer> amount){ArrayList<ShapelessItem> pool=pool(inv);ArrayList<SVFrameIngredient> needs=new ArrayList<>();for(SVFrameRecipeIngredient i:ingredients)needs.add(i.getIngredient());ArrayList<ShapelessItem> result=matches(pool,needs);if(result==null)return null;if(amount!=null)amount.set(1);return inv.clone();} public ArrayList<ShapelessItem> matches(ArrayList<ShapelessItem> items,ArrayList<SVFrameIngredient> needs){ArrayList<ShapelessItem> work=ShapelessItem.deepCloneList(items);for(SVFrameIngredient need:needs){ShapelessItem found=null;for(ShapelessItem item:work)if(item.getAmount()>0&&need.matches(item.getStack(),null)){found=item;break;}if(found==null)return null;found.take(1);}for(ShapelessItem item:work)if(item.getAmount()>0)return null;return work;} public ArrayList<ShapelessItem> pool(SVFrameRecipeInventory inv){ArrayList<ShapelessItem> out=new ArrayList<>();int id=0;for(int y=0;y<inv.getHeight();y++)for(int x=0;x<inv.getWidth();x++){ItemStack s=inv.getItemAt(x,y);if(s!=null&&!s.isEmpty())out.add(new ShapelessItem(id++,s,x,y));}return out;} }
